  "site.about.clubsEyebrow": "La red",
  "site.about.clubsText": "Cada club tiene su casa y su comunidad, con la misma coordinación técnica.",
  "site.about.clubsTitle": "Nuestros clubes",
  "site.about.heroText": "Judo Arte e Vida nació en el Algarve en torno a un entrenador y a una idea: el judo es mucho más que un deporte.",
  "site.about.heroTitle": "Una familia en torno al tatami",
  "site.about.story1": "Todo empieza con Matias Luwawa, judoca desde 1994. Entrenador desde 2006 y árbitro desde 2009, llegó a árbitro de élite y construyó, sala a sala, una red de clubes en el Algarve: Lagos, Albufeira, Alvor.",
  "site.about.story2": "Hoy Judo Arte e Vida reúne clubes, entrenadores, atletas y familias que comparten los mismos valores, y una plataforma que los conecta: inscripciones, cuotas, asistencias, competiciones y ranking en un solo lugar.",
  "site.about.storyEyebrow": "Nuestra historia",
  "site.about.storyTitle": "Del primer tatami a una red de clubes",
