  "site.tv.youtube": "Abrir en YouTube",
  "site.values.art.text": "La técnica como forma de arte: cada proyección es precisión, respeto y elegancia.",
  "site.values.art.title": "Arte",
  "site.values.discipline.text": "El saludo, la constancia, el respeto por el compañero: el judo enseña a caer y a levantarse.",
  "site.values.discipline.title": "Disciplina",
  "site.values.eyebrow": "Nuestros valores",
  "site.values.life.text": "Familias, amistades, comunidad: lo que se aprende en el tatami se queda para toda la vida.",
  "site.values.life.title": "Vida",
  "site.values.text": "Tres palabras en el nombre, una forma de estar en el tatami.",
  "site.values.title": "Arte, disciplina, vida",
  "site.vision.goalText": "Este es nuestro objetivo: una red que crece manteniendo la misma alma.",
  "site.vision.goalTitle": "Más clubes, más niños en el tatami, más familias implicadas",
  "site.vision.heroText": "Queremos que cada niño, cada familia y cada atleta encuentre en el judo disciplina, respeto y alegría: en cualquier club de la red.",
  "site.vision.heroTitle": "El judo como escuela de vida, al alcance de todos",
  "site.vision.mission1": "El judo tiene un código moral: respeto, sinceridad, valor, autocontrol. Lo llevamos del tatami a casa, al colegio, a la vida.",
  "site.vision.mission2": "Y queremos que los clubes puedan dedicarse a esto, no a la burocracia: por eso la red tiene una plataforma que se encarga sola de cuotas, asistencias, competiciones y cuentas.",
  "site.vision.missionEyebrow": "La misión",
  "site.vision.missionTitle": "Formar personas, no solo judocas",
  "site.vision.pillar.community.text": "Clubes, ayuntamientos, asociaciones y patrocinadores que crecen juntos en el Algarve.",
  "site.vision.pillar.community.title": "Comunidad",
  "site.vision.pillar.excellence.text": "De los primeros pasos al podio: campeonatos regionales, nacionales, veteranos.",
  "site.vision.pillar.excellence.title": "Excelencia deportiva",
  "site.vision.pillar.family.text": "Padres e hijos en el mismo tatami, familias implicadas en cada paso.",
  "site.vision.pillar.family.title": "Familia",
  "site.vision.pillar.inclusion.text": "Judo adaptado para personas con autismo y para personas ciegas y con baja visión: el tatami es de todos.",
  "site.vision.pillar.inclusion.title": "Inclusión",
  "site.vision.pillar.innovation.text": "Tecnología al servicio del judo: menos papel, más tiempo en el tatami.",
  "site.vision.pillar.innovation.title": "Innovación",
  "site.vision.pillar.values.text": "El saludo, el respeto por el compañero, la disciplina: el arte antes que la victoria.",
  "site.vision.pillar.values.title": "Valores",
